const jobs = [];

// Process Arbeitnow jobs
if ($input.first().json.data) {
  for (const job of $input.first().json.data) {
    const title = job.title || '';
    const desc = job.description || '';
    const text = (title + ' ' + desc).toLowerCase();

    // Check if relevant to skills
    const skillKeywords = ['python', 'machine learning', 'data science', 'ai', 'ml', 'deep learning', 'nlp', 'data analyst', 'software engineer', 'developer', 'intern', 'internship', 'fresher', 'junior', 'backend', 'frontend', 'langchain', 'llm'];

    const excludeKeywords = ['tax', 'accounting', 'finance', 'manufacturing', 'hr', 'sales', 'marketing', 'operations', 'legal', 'insurance'];

    const hasSkill = skillKeywords.some(kw => text.includes(kw));
    const hasExclude = excludeKeywords.some(kw => text.includes(kw));

    // Check location - India or Remote only
    const location = (job.location || '').toLowerCase();
    const remote = job.remote;
    const indiaKeywords = ['india', 'bangalore', 'hyderabad', 'chennai', 'pune', 'mumbai', 'delhi', 'remote', 'worldwide', 'global'];
    const isGoodLocation = remote || indiaKeywords.some(kw => location.includes(kw));

    if (hasSkill && !hasExclude && isGoodLocation) {
      jobs.push({
        title: title,
        company: job.company_name || 'Unknown',
        location: job.location || 'Remote',
        url: job.url || '',
        description: desc.substring(0, 500),
        platform: 'Arbeitnow',
        salary: job.salary || '',
        job_type: title.toLowerCase().includes('intern') ? 'internship' : 'full-time'
      });
    }
  }
}

