const jobs = $input.all().map(item => item.json);
const uniqueJobs = [];
const seenUrls = new Set();

for (const job of jobs) {
  if (job.url && !seenUrls.has(job.url)) {
    seenUrls.add(job.url);
    uniqueJobs.push(job);
  }
}

return uniqueJobs.map(job => ({ json: job }));

const jobs = $input.all().map(item => item.json);
const results = [];

for (const job of jobs) {
  const title = job.title || '';
  const desc = job.description || '';
  const text = (title + ' ' + desc).toLowerCase();

  let score = 5;

  // Good keywords increase score
  const goodKw = ['python', 'machine learning', 'ai', 'data science', 'deep learning', 'nlp', 'intern', 'fresher', 'junior', 'langchain', 'llm'];
  for (const kw of goodKw) {
    if (text.includes(kw)) score += 1;
  }

  // Bad keywords decrease score
  const badKw = ['operations', 'cybersecurity', 'finance', 'data entry', 'annotation'];
  for (const kw of badKw) {
    if (text.includes(kw)) score -= 2;
  }

  // Bonus for intern/junior
  if (title.toLowerCase().includes('intern')) score += 1;
  if (title.toLowerCase().includes('junior') || title.toLowerCase().includes('fresher')) score += 1;

  score = Math.max(1, Math.min(10, score));

  // Only keep jobs with score >= 4
  if (score >= 4) {
    results.push({
      ...job,
      fit_score: score,
      generated_at: new Date().toISOString()
    });
  }
}

return results.map(r => ({ json: r }));
